269→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
270→// Returns the checkpoint ID string and any condensation error.
271→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
272→	var checkpointIDStr string
273→	var condenseErr error
274→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
275→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
276→		condenseErr = err
277→	}
278→
279→	// Single load serves both checkpoint ID extraction and finalization
280→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
281→	if loadErr != nil {
282→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
283→		return checkpointIDStr, condenseErr
284→	}
285→	if state == nil {
286→		return checkpointIDStr, condenseErr
287→	}
288→
289→	if condenseErr == nil {
290→		checkpointIDStr = state.LastCheckpointID.String()
291→	}
292→
293→	now := time.Now()
294→	state.LastInteractionTime = &now
295→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
296→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
297→	}
298→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
299→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
300→	}
301→
302→	return checkpointIDStr, condenseErr
303→}
