305→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
306→// project directories if needed. For Gemini, rejects sessions started from subdirectories
307→// since hooks don't fire correctly in that case.
308→func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, agentType types.AgentType, ag agent.Agent) (string, error) {
309→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
310→	if err != nil {
311→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
312→	}
313→	// Agents use cwd-derived project directories, so the transcript may be stored under
314→	// a different project directory if the session was started from a different working directory.
315→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
316→		if found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag); searchErr == nil {
317→			// Gemini CLI hooks only fire correctly when started from the repo root.
318→			// If the transcript is in a different project directory, the session was started
319→			// from a subdirectory where SessionEnd (and other hooks) won't execute properly,
320→			// resulting in incomplete metadata. Reject the attach in this case.
321→			if agentType == agent.AgentTypeGemini {
322→				return "", fmt.Errorf("there was no Entire metadata found for session %s so it cannot be attached.", sessionID)
323→			}
324→			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
325→			transcriptPath = found
326→		} else {
327→			logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
328→		}
329→	}
330→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
331→		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
332→	}
333→	return transcriptPath, nil
334→}
