336→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
337→// When force is true, it amends without prompting.
338→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
339→	// Get HEAD commit info
340→	repo, err := openRepository(ctx)
341→	if err != nil {
342→		return fmt.Errorf("failed to open repository: %w", err)
343→	}
344→	headRef, err := repo.Head()
345→	if err != nil {
346→		return fmt.Errorf("failed to get HEAD: %w", err)
347→	}
348→	headCommit, err := repo.CommitObject(headRef.Hash())
349→	if err != nil {
350→		return fmt.Errorf("failed to get HEAD commit: %w", err)
351→	}
352→
353→	shortHash := headRef.Hash().String()[:7]
354→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
355→
356→	// Check if the commit already has this checkpoint trailer
357→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
358→		fmt.Fprintf(w, "\nLast commit already has an Entire-Checkpoint trailer.\n")
359→		return nil
360→	}
361→
362→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
363→
364→	amend := true
365→	if !force {
366→		form := NewAccessibleForm(
367→			huh.NewGroup(
368→				huh.NewConfirm().
369→					Title("Amend the last commit in this branch?").
370→					Affirmative("Y").
371→					Negative("n").
372→					Value(&amend),
373→			),
374→		)
375→		if err := form.Run(); err != nil {
376→			return fmt.Errorf("prompt failed: %w", err)
377→		}
378→	}
379→
380→	if !amend {
381→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
382→		return nil
383→	}
384→
385→	// Amend the commit with the checkpoint trailer
386→	newMessage := fmt.Sprintf("%s\n\n%s: %s\n", strings.TrimRight(headCommit.Message, "\n"), trailers.CheckpointTrailerKey, checkpointIDStr)
387→
388→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
389→	if output, err := cmd.CombinedOutput(); err != nil {
390→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
391→	}
392→
393→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
394→	return nil
395→}
