397→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
398→// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
399→func extractFirstPromptFromTranscript(data []byte) string {
400→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
401→	lines, err := transcript.ParseFromBytes(data)
402→	if err == nil {
403→		for _, line := range lines {
404→			if line.Type == transcript.TypeUser {
405→				prompt := extractTextFromMessage(line.Message)
406→				if prompt != "" {
407→					return prompt
408→				}
409→			}
410→		}
411→	}
412→
413→	// Fallback: try Gemini JSON format {"messages": [...]}
414→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
415→		return prompts[0]
416→	}
417→
418→	return ""
419→}
420→
421→// extractTextFromMessage extracts the text content from a transcript message.
422→func extractTextFromMessage(msg json.RawMessage) string {
423→	// Try string content first (simple user messages)
424→	var simple struct {
425→		Content string `json:"content"`
426→	}
427→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
428→		return simple.Content
429→	}
430→
431→	// Try array content (messages with tool results, text blocks, etc.)
432→	var array struct {
433→		Content []struct {
434→			Type string `json:"type"`
435→			Text string `json:"text"`
436→		} `json:"content"`
437→	}
438→	if err := json.Unmarshal(msg, &array); err == nil {
439→		for _, block := range array.Content {
440→			if block.Type == "text" && block.Text != "" {
441→				return block.Text
442→			}
443→		}
444→	}
445→
446→	return ""
447→}
