449→// normalizeGeminiTranscript re-serializes a Gemini JSON transcript so that all
450→// content fields are plain strings. Gemini user messages store content as
451→// [{"text":"..."}] arrays, but the UI expects string content. Parsing through
452→// geminicli.ParseTranscript normalizes this via GeminiMessage.UnmarshalJSON.
453→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
454→	parsed, err := geminicli.ParseTranscript(data)
455→	if err != nil {
456→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
457→	}
458→	normalized, err := json.MarshalIndent(parsed, "", "  ")
459→	if err != nil {
460→		return nil, fmt.Errorf("failed to re-serialize Gemini transcript: %w", err)
461→	}
462→	return normalized, nil
463→}
