465→// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
466→// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
467→func countUserTurns(data []byte) int {
468→	// Try JSONL format first — use extractTextFromMessage to distinguish
469→	// real user prompts from tool_result messages (both have type "user").
470→	lines, err := transcript.ParseFromBytes(data)
471→	if err == nil {
472→		count := 0
473→		for _, line := range lines {
474→			if line.Type == transcript.TypeUser {
475→				if extractTextFromMessage(line.Message) != "" {
476→					count++
477→				}
478→			}
479→		}
480→		if count > 0 {
481→			return count
482→		}
483→	}
484→
485→	// Fallback: Gemini JSON format
486→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
487→		return len(prompts)
488→	}
489→
490→	return 0
491→}
