493→// extractModelFromTranscript extracts the model name from a JSONL transcript.
494→// Best-effort: returns empty string if the transcript format doesn't include model info
495→// (e.g., Gemini stores model info in hook events, not the transcript).
496→func extractModelFromTranscript(data []byte) string {
497→	lines, err := transcript.ParseFromBytes(data)
498→	if err != nil {
499→		return ""
500→	}
501→
502→	for _, line := range lines {
503→		if line.Type != transcript.TypeAssistant {
504→			continue
505→		}
506→		var msg struct {
507→			Model string `json:"model"`
508→		}
509→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
510→			return msg.Model
511→		}
512→	}
513→	return ""
514→}
