516→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
517→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
518→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
519→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
520→func estimateSessionDuration(data []byte) int64 {
521→	type timestamped struct {
522→		Timestamp string `json:"timestamp"`
523→	}
524→
525→	var first, last time.Time
526→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
527→		if len(rawLine) == 0 {
528→			continue
529→		}
530→		var ts timestamped
531→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
532→			continue
533→		}
534→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
535→		if err != nil {
536→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
537→			if err != nil {
538→				continue
539→			}
540→		}
541→		if first.IsZero() {
542→			first = parsed
543→		}
544→		last = parsed
545→	}
546→
547→	if first.IsZero() || last.IsZero() || !last.After(first) {
548→		return 0
549→	}
550→	return last.Sub(first).Milliseconds()
551→}
