 903→export async function processSessionsPushEvent(
 904→  eventType: string,
 905→  payload: Record<string, unknown>,
 906→  db: Db,
 907→  env: Env
 908→): Promise<void> {
 909→  if (eventType !== "push") return;
 910→
 911→  const repo = payload.repository as Record<string, unknown> | undefined;
 912→  if (!repo?.full_name) return;
 913→
 914→  const repoFullName = repo.full_name as string;
 915→  const ref = payload.ref as string | undefined;
 916→
 917→  // Only process pushes to CHECKPOINT_BRANCH
 918→  if (ref !== `refs/heads/${CHECKPOINT_BRANCH}`) return;
 919→
 920→  const deleted = payload.deleted as boolean | undefined;
 921→  if (deleted) {
 922→    logCheckpointMetric("sessions_branch_deleted", { repo: repoFullName });
 923→    return;
 924→  }
 925→
 926→  // Find the global repo record
 927→  const repoGithubId = repo.id as number;
 928→  const repoRecord = await db.repos.getByGithubId(repoGithubId);
 929→  if (!repoRecord) {
 930→    logCheckpointMetric("skip_repo_not_found", { repo: repoFullName });
 931→    return;
 932→  }
 933→
 934→  // Get commits from push payload
 935→  const commits = payload.commits as Array<Record<string, unknown>> | undefined;
 936→  if (!commits?.length) return;
 937→
 938→  // Extract checkpoint IDs from commit subjects and trailers.
 939→  // Commits on the metadata branch use "Checkpoint: <id>" as the subject line,
 940→  // which parseTrailers() doesn't reach (it stops at the blank line separator).
 941→  // Also check trailers for backwards compatibility.
 942→  const CHECKPOINT_SUBJECT_RE = /^Checkpoint:\s*(\S+)$/;
 943→  const checkpointIds: string[] = [];
 944→  for (const commit of commits) {
 945→    const message = commit.message as string;
 946→
 947→    // Check subject line (first line of commit message)
 948→    const subject = message.split("\n")[0];
 949→    const subjectMatch = subject.match(CHECKPOINT_SUBJECT_RE);
 950→    if (subjectMatch) {
 951→      checkpointIds.push(subjectMatch[1]);
 952→      continue;
 953→    }
 954→
 955→    // Fallback: check trailers (e.g., squashed commits)
 956→    const trailers = parseTrailers(message);
 957→    const commitCheckpointIds = trailers["Checkpoint"] ?? [];
 958→    checkpointIds.push(...commitCheckpointIds);
 959→  }
 960→
 961→  if (checkpointIds.length === 0) {
 962→    logCheckpointMetric("no_session_checkpoints", { repo: repoFullName });
 963→    return;
 964→  }
 965→
 966→  logCheckpointMetric("processing_sessions", { repo: repoFullName, count: checkpointIds.length });
 967→
 968→  // Validate installation exists before processing
 969→  // This prevents unauthorized data modification from compromised webhook secrets
 970→  const installationId = await validateInstallation(payload, db, `Sessions push ${repoFullName}`);
 971→  if (installationId === null) {
 972→    logCheckpointMetric("skip_no_installation", { repo: repoFullName });
 973→    return;
 974→  }
 975→
 976→  // Get app installation token
 977→  let token: string | null = null;
 978→  try {
 979→    token = await getInstallationToken(
 980→      installationId,
 981→      {
 982→        appId: env.GITHUB_CLIENT_ID,
 983→        privateKey: env.GITHUB_APP_PRIVATE_KEY,
 984→      },
 985→      env.ENTIRE_CACHE
 986→    );
 987→  } catch (err) {
 988→    logCheckpointMetric("installation_token_unavailable", {
 989→      repo: repoFullName,
 990→      installationId,
 991→      error: err instanceof Error ? err.message : String(err),
 992→    });
 993→  }
 994→
 995→  // If no token, we can't fetch session files - skip processing
 996→  if (!token) {
 997→    logCheckpointMetric("skip_no_token", { repo: repoFullName });
 998→    return;
 999→  }
1000→
1001→  trace.getActiveSpan()?.setAttribute("github.installation_id", installationId);
1002→
1003→  try {
1004→    // Batch fetch all session data using GraphQL
1005→    const sessionDataResult = await fetchSessionDataBatch(repoFullName, checkpointIds, token);
1006→
1007→    if (sessionDataResult.failedItems.length > 0) {
1008→      logCheckpointMetric("sessions_partial_failure", {
1009→        repo: repoFullName,
1010→        failed: sessionDataResult.failedItems.length,
1011→        errors: sessionDataResult.errors,
1012→      });
1013→    }
1014→
1015→    // Build checkpoint data array
1016→    const checkpointDataArray = buildCheckpointDataFromSessions(checkpointIds, sessionDataResult);
1017→
1018→    // Upsert checkpoints for the global repo (once, not per-user)
1019→    const successCount = await db.checkpoints.upsertBatch(repoRecord.id, checkpointDataArray);
1020→
1021→    // Fetch and store stripped transcripts (needed by both search and summary consumers)
1022→    // Done before queue sends so downstream consumers find transcripts in DB
1023→    try {
1024→      const sessionCountMap = new Map(checkpointDataArray.map((c) => [c.checkpoint_id, c.session_count]));
1025→      const stored = await fetchAndStoreTranscripts(db, repoRecord.id, repoFullName, checkpointIds, sessionCountMap, token);
1026→      if (stored > 0) {
1027→        logCheckpointMetric("transcripts_stored", { repo: repoFullName, stored, total: checkpointIds.length });
1028→      }
1029→    } catch (transcriptErr) {
1030→      // Log and continue — summary consumer has a GitHub fallback path
1031→      logCheckpointMetric("transcript_prefetch_error", {
1032→        repo: repoFullName,
1033→        error: transcriptErr instanceof Error ? transcriptErr.message : String(transcriptErr),
1034→      });
1035→    }
1036→
1037→    // Queue checkpoints for search indexing (non-blocking, best-effort)
1038→    if (env.SEARCH_INDEX_QUEUE) {
1039→      try {
1040→        await env.SEARCH_INDEX_QUEUE.send({
1041→          repoId: repoRecord.id,
1042→          checkpointIds,
1043→          queuedAt: new Date().toISOString(),
1044→        } satisfies SearchIndexMessage);
1045→      } catch (queueErr) {
1046→        console.error("[webhook] search_index_queue_error", repoRecord.id, queueErr);
1047→      }
1048→    }
1049→
1050→    // Queue checkpoints for proactive summary generation (non-blocking, best-effort)
1051→    // Gate behind SUMMARY_ENABLED_ORGS — only send queue messages for enabled orgs
1052→    // (The consumer also checks, but this avoids unnecessary queue messages + upsertPending writes)
1053→    const summaryOrgAllowed = isOrgAllowed(env.SUMMARY_ENABLED_ORGS, repoFullName);
1054→    if (env.SUMMARY_QUEUE && summaryOrgAllowed) {
1055→      try {
1056→        const queuedAt = new Date().toISOString();
1057→        for (const cpId of checkpointIds) {
1058→          await db.summaries.upsertPending(repoRecord.id, cpId, queuedAt);
1059→          await env.SUMMARY_QUEUE.send({
1060→            repoId: repoRecord.id,
1061→            checkpointId: cpId,
1062→            queuedAt,
1063→          } satisfies SummaryQueueMessage);
1064→        }
1065→      } catch (queueErr) {
1066→        console.error("[webhook] summary_queue_error", repoRecord.id, queueErr);
1067→      }
1068→    } else if (env.SUMMARY_QUEUE && !summaryOrgAllowed) {
1069→      logCheckpointMetric("skip_summary_org_not_allowed", { repo: repoFullName });
1070→    }
1071→
1072→    // Invalidate transcript cache for affected checkpoints
1073→    // Session data changes mean transcripts may have changed
1074→    await Promise.all(
1075→      checkpointIds.map((id) =>
1076→        env.ENTIRE_CACHE.delete(buildTranscriptCacheKey(repoFullName, id))
1077→      )
1078→    );
1079→
1080→    // Count session metrics for monitoring
1081→    const totalSessions = checkpointDataArray.reduce((sum, cp) => sum + (cp.session_count ?? 0), 0);
1082→    const checkpointsWithSessions = checkpointDataArray.filter((cp) => cp.sessions != null).length;
1083→
1084→    logCheckpointMetric("sessions_completed", {
1085→      repo: repoFullName,
1086→      successCount,
1087→      totalSessions,
1088→      checkpointsWithSessions,
1089→      checkpointsTotal: checkpointDataArray.length,
1090→    });
1091→  } catch (err) {
1092→    logCheckpointMetric("error_sessions", {
1093→      repo: repoFullName,
1094→      error: err instanceof Error ? err.message : String(err),
1095→    });
1096→    throw err; // Re-throw to trigger webhook retry mechanism
1097→  }
1098→}
