1100→// Process push to any branch (except CHECKPOINT_BRANCH) - stores commit data
1101→export async function processCommitPushEvent(
1102→  eventType: string,
1103→  payload: Record<string, unknown>,
1104→  db: Db,
1105→  env: Env
1106→): Promise<void> {
1107→  if (eventType !== "push") return;
1108→
1109→  const repo = payload.repository as Record<string, unknown> | undefined;
1110→  if (!repo?.full_name) return;
1111→
1112→  const repoFullName = repo.full_name as string;
1113→  const ref = payload.ref as string | undefined;
1114→  const deleted = payload.deleted as boolean | undefined;
1115→
1116→  // Only process branch pushes (not tags)
1117→  if (!ref?.startsWith("refs/heads/")) return;
1118→  const branch = ref.replace("refs/heads/", "");
1119→
1120→  // Skip CHECKPOINT_BRANCH - handled by processSessionsPushEvent
1121→  if (branch === CHECKPOINT_BRANCH) return;
1122→
1123→  // Skip TRAILS_BRANCH - handled by processTrailsPushEvent
1124→  if (branch === TRAILS_BRANCH) return;
1125→
1126→  // Validate installation exists before processing any DB operations
1127→  // This prevents unauthorized data modification from compromised webhook secrets
1128→  const installationId = await validateInstallation(payload, db, `Commit push ${repoFullName}`);
1129→  if (installationId === null) {
1130→    logCheckpointMetric("skip_no_installation", { repo: repoFullName, branch });
1131→    return;
1132→  }
1133→
1134→  trace.getActiveSpan()?.setAttribute("github.installation_id", installationId);
1135→
1136→  // Find the global repo record
1137→  const repoGithubId = repo.id as number;
1138→  const repoRecord = await db.repos.getByGithubId(repoGithubId);
1139→  if (!repoRecord) {
1140→    logCheckpointMetric("skip_repo_not_found", { repo: repoFullName });
1141→    return;
1142→  }
1143→
1144→  // Handle branch deletion
1145→  if (deleted) {
1146→    const deletedCount = await db.checkpoints.deleteCommitsByBranch(repoRecord.id, branch);
1147→    const orphansDeleted = await db.checkpoints.deleteOrphaned(repoRecord.id);
1148→    if (deletedCount > 0 || orphansDeleted > 0) {
1149→      await db.checkpoints.recalculateCount(repoRecord.id);
1150→    }
1151→    logCheckpointMetric("branch_deleted", { repo: repoFullName, branch, deletedCount, orphansDeleted });
1152→    return;
1153→  }
1154→
1155→  // Handle force push: clear stale checkpoint commits for this branch and queue re-sync.
1156→  // Force pushes rewrite history, so old checkpoint commits may no longer be reachable.
1157→  // The push payload only contains newly pushed commits (not the full branch), so we
1158→  // delete stale entries immediately and queue a full backfill to re-discover the rest.
1159→  const forced = payload.forced as boolean | undefined;
1160→  if (forced) {
1161→    const deletedCount = await db.checkpoints.deleteCommitsByBranch(repoRecord.id, branch);
1162→    const orphansDeleted = await db.checkpoints.deleteOrphaned(repoRecord.id);
1163→    if (deletedCount > 0 || orphansDeleted > 0) {
1164→      await db.checkpoints.recalculateCount(repoRecord.id);
1165→    }
1166→
1167→    // Invalidate backfill state so next sync does a full re-discovery
1168→    await db.checkpoints.updateSyncState(repoRecord.id, { resetBackfill: true });
1169→
1170→    // Queue immediate re-sync to backfill reachable checkpoints
1171→    if (env?.REPO_SYNC_QUEUE) {
1172→      await queueRepoSyncBatch(env.REPO_SYNC_QUEUE, [{ id: repoRecord.id }], "manual", 10);
1173→    }
1174→
1175→    logCheckpointMetric("force_push_cleanup", { repo: repoFullName, branch, deletedCount, orphansDeleted });
1176→  }
1177→
1178→  // Get commits from push payload
1179→  const commits = payload.commits as Array<Record<string, unknown>> | undefined;
1180→  if (!commits?.length) return;
1181→
1182→  const defaultBranch = repoRecord.default_branch || repo.default_branch || "main";
1183→
1184→  // Extract checkpoint IDs from Entire-Checkpoint trailers in commit messages.
1185→  // On non-default branches, skip non-distinct commits (distinct=false means the
1186→  // commit already existed in the repository / was pushed before, e.g. via "Update branch" merge).
1187→  const checkpointCommits: Array<{
1188→    sha: string;
1189→    message: string;
1190→    checkpointId: string;
1191→    author: { name: string; username?: string };
1192→    timestamp: string;
1193→  }> = [];
1194→
1195→  let skippedNonDistinct = 0;
1196→
1197→  for (const commit of commits) {
1198→    if (branch !== defaultBranch && commit.distinct === false) {
1199→      skippedNonDistinct++;
1200→      continue;
1201→    }
1202→
1203→    const message = commit.message as string;
1204→    const checkpointIds = extractCheckpointIds(message);
1205→
1206→    for (const checkpointId of checkpointIds) {
1207→      checkpointCommits.push({
1208→        sha: commit.id as string,
1209→        message,
1210→        checkpointId,
1211→        author: {
1212→          name: (commit.author as Record<string, unknown>)?.name as string,
1213→          username: (commit.author as Record<string, unknown>)?.username as string | undefined,
1214→        },
1215→        timestamp: commit.timestamp as string,
1216→      });
1217→    }
1218→  }
